        uint before = c.getBalance(address(this));

        bool reverted;
        try c.addToBalance{value: amount}() { reverted = false; } catch { reverted = true; }

        uint afterBal = c.getBalance(address(this));

        // Caller's balance after a successful call must be exactly before + amount,
        // and a reverted call must leave the balance untouched. Both branches
        // obey the unsigned 256-bit addition rule enforced by add_uint256.
        assert(afterBal == (reverted ? before : before + amount));
